mapper.select:

where l.del_flag = '0'
and l.model_config_id = #{modelConfigId}
and l.request_type = #{requestType}
and l.business_type = #{businessType}
and l.success = #{success}

    and l.create_time >= #{params.beginTime}


    and l.create_time <= concat(#{params.endTime}, ' 23:59:59')

order by l.id desc
